        "content": "<div class=\"relative w-full max-w-6xl mx-auto flex-1 flex flex-col items-center justify-center min-h-0\">\n<!-- Slider Container -->\n<div class=\"relative w-full overflow-hidden rounded-2xl shadow-lg border border-slate-200\" style=\"aspect-ratio: 16/9;\">\n<div class=\"flex transition-transform duration-500 ease-in-out h-full\" id=\"carousel-track\" style=\"width: 500%;\">\n<!-- Item 1 -->\n<div class=\"w-1/5 h-full flex-shrink-0 relative cursor-pointer\" onclick=\"openLightbox('Loi%20sai/Loi%20sai%201.jpg')\">\n<img alt=\"Cỡ chữ không đồng nhất\" class=\"w-full h-full object-contain bg-slate-50\" src=\"Loi sai/Loi sai 1.jpg\"/>\n<div class=\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-4\">\n<span class=\"bg-rose-500 text-white px-4 py-1.5 rounded-full font-medium text-base inline-flex items-center shadow-md\">\n<i class=\"fa-solid fa-circle-exclamation mr-2\"></i>Cỡ chữ không đồng nhất\n                                </span>\n</div>\n</div>\n<!-- Item 2 -->\n<div class=\"w-1/5 h-full flex-shrink-0 relative cursor-pointer\" onclick=\"openLightbox('Loi%20sai/Loi%20sai%202.jpg')\">\n<img alt=\"Lỗi hiển thị kí hiệu\" class=\"w-full h-full object-contain bg-slate-50\" src=\"Loi sai/Loi sai 2.jpg\"/>\n<div class=\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-4\">\n<span class=\"bg-amber-500 text-white px-4 py-1.5 rounded-full font-medium text-base inline-flex items-center shadow-md\">\n<i class=\"fa-solid fa-circle-exclamation mr-2\"></i>Lỗi hiển thị kí hiệu\n                                </span>\n</div>\n</div>\n<!-- Item 3 -->\n<div class=\"w-1/5 h-full flex-shrink-0 relative cursor-pointer\" onclick=\"openLightbox('Loi%20sai/Loi%20sai%203.jpg')\">\n<img alt=\"Thông tin và ghi chú\" class=\"w-full h-full object-contain bg-slate-50\" src=\"Loi sai/Loi sai 3.jpg\"/>\n<div class=\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-4\">\n<span class=\"bg-brand-orange text-white px-4 py-1.5 rounded-full font-medium text-base inline-flex items-center shadow-md\">\n<i class=\"fa-solid fa-circle-exclamation mr-2\"></i>Thông tin và ghi chú\n                                </span>\n</div>\n</div>\n<!-- Item 4 -->\n<div class=\"w-1/5 h-full flex-shrink-0 relative cursor-pointer\" onclick=\"openLightbox('Loi%20sai/Loi%20sai%204.jpg')\">\n<img alt=\"Lỗi hiển thị kí hiệu\" class=\"w-full h-full object-contain bg-slate-50\" src=\"Loi sai/Loi sai 4.jpg\"/>\n<div class=\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-4\">\n<span class=\"bg-brand-blue text-white px-4 py-1.5 rounded-full font-medium text-base inline-flex items-center shadow-md\">\n<i class=\"fa-solid fa-circle-exclamation mr-2\"></i>Lỗi hiển thị kí hiệu\n                                </span>\n</div>\n</div>\n<!-- Item 5 -->\n<div class=\"w-1/5 h-full flex-shrink-0 relative cursor-pointer\" onclick=\"openLightbox('Loi%20sai/Loi%20sai%206.jpg')\">\n<img alt=\"Nội dung bài học chưa đầy đủ\" class=\"w-full h-full object-contain bg-slate-50\" src=\"Loi sai/Loi sai 6.jpg\"/>\n<div class=\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-4\">\n<span class=\"bg-purple-500 text-white px-4 py-1.5 rounded-full font-medium text-base inline-flex items-center shadow-md\">\n<i class=\"fa-solid fa-circle-exclamation mr-2\"></i>Nội dung bài học chưa đầy đủ\n                                </span>\n</div>\n</div>\n</div>\n<!-- Prev / Next buttons -->\n<button class=\"absolute left-3 top-1/2 -translate-y-1/2 w-12 h-12 bg-white/90 hover:bg-white rounded-full shadow-lg flex items-center justify-center text-brand-blue text-2xl transition-all hover:scale-110 z-20\" onclick=\"moveCarousel(-1)\">\n<i class=\"fa-solid fa-chevron-left\"></i>\n</button>\n<button class=\"absolute right-3 top-1/2 -translate-y-1/2 w-12 h-12 bg-white/90 hover:bg-white rounded-full shadow-lg flex items-center justify-center text-brand-blue text-2xl transition-all hover:scale-110 z-20\" onclick=\"moveCarousel(1)\">\n<i class=\"fa-solid fa-chevron-right\"></i>\n</button>\n</div>\n<!-- Indicator Dots -->\n<div class=\"flex items-center gap-3 mt-5\">\n<button class=\"carousel-dot w-3 h-3 rounded-full bg-brand-blue transition-all duration-300 scale-125\" data-index=\"0\" onclick=\"goToCarousel(0)\"></button>\n<button class=\"carousel-dot w-3 h-3 rounded-full bg-slate-300 transition-all duration-300\" data-index=\"1\" onclick=\"goToCarousel(1)\"></button>\n<button class=\"carousel-dot w-3 h-3 rounded-full bg-slate-300 transition-all duration-300\" data-index=\"2\" onclick=\"goToCarousel(2)\"></button>\n<button class=\"carousel-dot w-3 h-3 rounded-full bg-slate-300 transition-all duration-300\" data-index=\"3\" onclick=\"goToCarousel(3)\"></button>\n<button class=\"carousel-dot w-3 h-3 rounded-full bg-slate-300 transition-all duration-300\" data-index=\"4\" onclick=\"goToCarousel(4)\"></button>\n<span class=\"ml-3 text-base text-slate-500 font-medium\" id=\"carousel-counter\">1 / 5</span>\n</div>\n</div>",
