        "content": "<div class=\"w-full h-full grid grid-cols-1 md:grid-cols-3 print:grid-cols-3 gap-6 pb-4\">\n<!-- PDF 1 -->\n<div class=\"w-full h-full min-h-[400px] md:min-h-0 bg-slate-50 rounded-xl border-2 border-slate-200 overflow-hidden shadow-sm flex flex-col\">\n<div class=\"p-3 bg-slate-200 font-bold text-slate-700 text-center border-b border-slate-300\">Phiếu\n                        bài (Đề BTTL và BTVN)</div>\n<iframe class=\"w-full flex-1 border-none\" src=\"Phiếu bài (Đề BT trên lớp và BTVN).pdf\"></iframe>\n</div>\n<!-- PDF 2 -->\n<div class=\"w-full h-full min-h-[400px] md:min-h-0 bg-slate-50 rounded-xl border-2 border-slate-200 overflow-hidden shadow-sm flex flex-col\">\n<div class=\"p-3 bg-slate-200 font-bold text-slate-700 text-center border-b border-slate-300\">Hướng\n                        dẫn BTVN (HDBTVN)</div>\n<iframe class=\"w-full flex-1 border-none\" src=\"HDBTVN.pdf\"></iframe>\n</div>\n<!-- PDF 3 -->\n<div class=\"w-full h-full min-h-[400px] md:min-h-0 bg-slate-50 rounded-xl border-2 border-slate-200 overflow-hidden shadow-sm flex flex-col\">\n<div class=\"p-3 bg-slate-200 font-bold text-slate-700 text-center border-b border-slate-300\">Nội\n                        dung bài học (NDBH)</div>\n<iframe class=\"w-full flex-1 border-none\" src=\"NDBH.pdf\"></iframe>\n</div>\n</div>",
